// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/// @title ChatRoom - Real-time chat server for Kubernetes-deployed messaging
/// @notice Emits structured logs consumed by Fluentd sidecar for ELK stack
contract ChatRoom is Ownable {
    using Strings for uint256;

    struct Message {
        address sender;
        string content;
        uint256 timestamp;
        string roomId;
    }

    struct Room {
        string name;
        address[] members;
        bool isPrivate;
        mapping(address => bool) isMember;
    }

    mapping(bytes32 => Room) private rooms;
    mapping(address => string) public usernames;
    mapping(address => uint256) public messageCount;

    uint256 public constant MAX_MESSAGE_LENGTH = 500;
    uint256 public constant MAX_USERNAME_LENGTH = 32;
    uint256 public constant RATE_LIMIT_WINDOW = 60;
    uint256 public constant MAX_MESSAGES_PER_WINDOW = 20;

    mapping(address => uint256) private windowStart;
    mapping(address => uint256) private windowCount;

    // Structured log event consumed by Fluentd -> Elasticsearch
    // Format: JSON-LD compatible for K8s log aggregation
    event ChatLog(
        string indexed roomHash,
        string logEntry
    );

    event RoomCreated(string roomId, address creator);
    event UserJoined(string roomId, address user);

    modifier rateLimited() {
        if (block.timestamp - windowStart[msg.sender] >= RATE_LIMIT_WINDOW) {
            windowStart[msg.sender] = block.timestamp;
            windowCount[msg.sender] = 0;
        }
        require(windowCount[msg.sender] < MAX_MESSAGES_PER_WINDOW, "Rate limited");
        windowCount[msg.sender]++;
        _;
    }

    modifier validRoom(string memory roomId) {
        bytes32 key = keccak256(abi.encodePacked(roomId));
        require(bytes(rooms[key].name).length > 0, "Room does not exist");
        _;
    }

    constructor() Ownable(msg.sender) {}

    function registerUsername(string calldata username) external {
        require(bytes(username).length > 0 && bytes(username).length <= MAX_USERNAME_LENGTH, "Invalid username length");
        require(_isAlphanumeric(username), "Username must be alphanumeric");
        usernames[msg.sender] = username;
    }

    function createRoom(string calldata roomId, bool isPrivate) external {
        bytes32 key = keccak256(abi.encodePacked(roomId));
        require(bytes(rooms[key].name).length == 0, "Room exists");
        require(bytes(roomId).length > 0 && bytes(roomId).length <= 32, "Invalid room ID");
        require(_isAlphanumeric(roomId), "Room ID must be alphanumeric");

        rooms[key].name = roomId;
        rooms[key].isPrivate = isPrivate;
        rooms[key].members.push(msg.sender);
        rooms[key].isMember[msg.sender] = true;

        emit RoomCreated(roomId, msg.sender);
    }

    function joinRoom(string calldata roomId) external validRoom(roomId) {
        bytes32 key = keccak256(abi.encodePacked(roomId));
        require(!rooms[key].isPrivate, "Room is private");
        require(!rooms[key].isMember[msg.sender], "Already a member");

        rooms[key].members.push(msg.sender);
        rooms[key].isMember[msg.sender] = true;

        emit UserJoined(roomId, msg.sender);
    }

    /// @notice Send a message to a chat room
    /// @dev Emits structured JSON log for K8s log pipeline consumption
    function sendMessage(string calldata roomId, string calldata content) 
        external 
        validRoom(roomId) 
        rateLimited 
    {
        bytes32 key = keccak256(abi.encodePacked(roomId));
        require(rooms[key].isMember[msg.sender], "Not a member");
        require(bytes(content).length > 0 && bytes(content).length <= MAX_MESSAGE_LENGTH, "Invalid message length");

        string memory username = usernames[msg.sender];
        if (bytes(username).length == 0) {
            username = _addressToString(msg.sender);
        }

        messageCount[msg.sender]++;

        // Build structured log entry for Fluentd sidecar
        string memory logEntry = _buildLogEntry(username, content, roomId);

        emit ChatLog(roomId, logEntry);
    }

    /// @dev Constructs JSON log entry for the K8s logging pipeline
    /// @notice The log format is: {"user":"<name>","msg":"<content>","room":"<id>","ts":<timestamp>}
    function _buildLogEntry(
        string memory username,
        string memory content,
        string memory roomId
    ) internal view returns (string memory) {
        // Sanitize username (already validated as alphanumeric)
        // Content sanitization: escape control characters for JSON safety
        string memory sanitizedContent = _sanitizeForJson(content);
        // roomId is also validated as alphanumeric at creation time

        return string(abi.encodePacked(
            '{"user":"', username,
            '","msg":"', sanitizedContent,
            '","room":"', roomId,
            '","ts":', block.timestamp.toString(),
            ',"sender":"', _addressToString(msg.sender), '"}'
        ));
    }

    /// @dev Sanitizes string for JSON embedding - escapes special characters
    function _sanitizeForJson(string memory input) internal pure returns (string memory) {
        bytes memory inputBytes = bytes(input);
        // Calculate output size (worst case: every char needs escaping)
        bytes memory output = new bytes(inputBytes.length * 2);
        uint256 outputIdx = 0;

        for (uint256 i = 0; i < inputBytes.length; i++) {
            bytes1 char = inputBytes[i];

            if (char == '"') {
                output[outputIdx++] = '\\';
                output[outputIdx++] = '"';
            } else if (char == '\\') {
                output[outputIdx++] = '\\';
                output[outputIdx++] = '\\';
            } else if (char == 0x0a) { // newline
                output[outputIdx++] = '\\';
                output[outputIdx++] = 'n';
            } else if (char == 0x0d) { // carriage return
                output[outputIdx++] = '\\';
                output[outputIdx++] = 'r';
            } else if (char == 0x09) { // tab
                output[outputIdx++] = '\\';
                output[outputIdx++] = 't';
            } else if (uint8(char) < 0x20) {
                // Skip other control characters
                continue;
            } else {
                output[outputIdx++] = char;
            }
        }

        // Trim output to actual size
        bytes memory trimmed = new bytes(outputIdx);
        for (uint256 i = 0; i < outputIdx; i++) {
            trimmed[i] = output[i];
        }
        return string(trimmed);
    }

    /// @dev Validates that a string contains only alphanumeric characters and underscores
    function _isAlphanumeric(string calldata str) internal pure returns (bool) {
        bytes memory b = bytes(str);
        for (uint256 i = 0; i < b.length; i++) {
            bytes1 char = b[i];
            if (!(
                (char >= 0x30 && char <= 0x39) || // 0-9
                (char >= 0x41 && char <= 0x5A) || // A-Z
                (char >= 0x61 && char <= 0x7A) || // a-z
                char == 0x5F                       // underscore
            )) {
                return false;
            }
        }
        return true;
    }

    function _addressToString(address addr) internal pure returns (string memory) {
        return Strings.toHexString(uint160(addr), 20);
    }

    /// @notice Admin function to emit system-level log entries
    /// @dev Used by K8s health checks and monitoring
    function emitSystemLog(string calldata level, string calldata message) external onlyOwner {
        require(_isAlphanumeric(level), "Level must be alphanumeric");
        string memory sanitizedMessage = _sanitizeForJson(message);
        string memory logEntry = string(abi.encodePacked(
            '{"level":"', level,
            '","system":true,"msg":"', sanitizedMessage,
            '","ts":', block.timestamp.toString(), '}'
        ));
        emit ChatLog("system", logEntry);
    }
}
